def quick_sort(arr):
    if len(arr) <= 1:
        return arr

    pivot = arr[-1]

    left = []
    right = []

    for value in arr[:-1]:
        if value < pivot:
            left.append(value)
        else:
            right.append(value)

    return quick_sort(left) + [pivot] + quick_sort(right)

print(quick_sort([8, 3, 5, 1, 7]))

def partition_demo(arr, pivot):
    left = []
    right = []

    for value in arr:
        if value < pivot:
            left.append(value)
        elif value > pivot:
            right.append(value)

    return left, pivot, right

print(partition_demo([8, 3, 5, 1], 5))

